import { memo, useCallback, useState } from "react";
import { Button, Checkbox, Icon, Rating } from "@kit/index.js";
import { useLocalized, useNumberFormat, useSearchState, useToggleFilter, useTrack, useTranslation } from "travel-platform";
import { FilterInfo } from "./FilterInfo.jsx";
import { useFilterFragment } from "./fragments.js";
import styles from "./FilterPanel.module.css";

function OptionLabel({ option }) {
    const localized = useLocalized();
    const label = localized(option.label);
    if (option.starCount)
        return <span className={styles.starLabel}>{label}<Rating value={option.starCount} label={label} size="smaller" /></span>;
    if (option.icon)
        return <span className={styles.iconLabel}><Icon name={option.icon.name} size="small" />{label}</span>;
    return label;
}

function FilterOptionCount({ count }) {
    const format = useNumberFormat();
    return <span className={count.value ? undefined : styles.zeroCount}>{format(count.value)}</span>;
}

const FilterOption = memo(function FilterOption({ option: fromList, checked, onToggle }) {
    const option = useFilterFragment("FilterOptionFields", fromList);
    const onChange = useCallback((event) => onToggle(option, event.target.checked), [onToggle, option]);
    return (
        <li className={styles.option} data-filter={option.urlId}>
            <Checkbox
                name={option.field}
                value={option.value}
                checked={checked}
                disabled={option.disabled && !checked}
                label={<OptionLabel option={option} />}
                count={<FilterOptionCount count={option.count} />}
                onChange={onChange}
                aria-label={option.a11yText}
                testId="filter-option"
            />
            {option.tooltip ? <FilterInfo tooltip={option.tooltip} /> : null}
        </li>
    );
});

export const CheckboxFilterGroup = memo(function CheckboxFilterGroup({ group, control }) {
    const t = useTranslation();
    const localized = useLocalized();
    const track = useTrack();
    const toggle = useToggleFilter();
    const { displayState } = useSearchState();
    const [expanded, setExpanded] = useState(false);
    const selected = displayState.filters;
    const onToggle = useCallback((option, on) => {
        track(on ? "accommodation.search_filter_selected" : "accommodation.search_filter_removed", { filter: option.urlId, group: group.field, payload: option.trackingPayload });
        toggle(option.urlId, on);
    }, [toggle, track, group.field]);
    const limit = expanded || !group.collapsedCount ? control.options.length : group.collapsedCount;
    const visible = control.options.slice(0, limit);
    return (
        <>
            <ul className={styles.options}>
                {visible.map((option) => <FilterOption key={option.urlId} option={option} checked={selected.includes(option.urlId)} onToggle={onToggle} />)}
            </ul>
            {group.showAllLabel && control.options.length > group.collapsedCount ? (
                <Button variant="tertiary" size="small" icon={expanded ? "chevron-up" : "chevron-down"} iconPosition="end" onClick={() => setExpanded(!expanded)} className={styles.showAll}>
                    {expanded ? t("filters.show_less") : localized(group.showAllLabel)}
                </Button>
            ) : null}
        </>
    );
});
