import { gql, useFragment } from "@apollo/client";
import { FILTERS, LOCALIZED } from "../../graphql/search.mjs";

const FILTER_FRAGMENTS = gql(FILTERS + LOCALIZED);

// Reads a filter option or group from the cache, falling back to the
// object passed down while the cache doesn't have it complete.
export function useFilterFragment(fragmentName, from) {
    const { data, complete } = useFragment({ fragment: FILTER_FRAGMENTS, fragmentName, from });
    return complete ? data : from;
}
