import { useCallback, useMemo } from "react";
import { RangeSlider } from "@kit/index.js";
import { useDebouncedCallback, useLocalized, useMoneyFormat, useSearchState, useTrack, useTranslation } from "travel-platform";

function useRangeFilter(control) {
    const { navigate } = useSearchState();
    return useCallback(([min, max]) => {
        const isDefault = min === control.min && max === control.max;
        navigate((state) => ({
            ...state,
            page: 0,
            filters: [...state.filters.filter((f) => !f.startsWith(`${control.urlPrefix}-`) && !f.startsWith(`${control.urlPrefix}=`)), ...(isDefault ? [] : [control.currency ? `${control.urlPrefix}-${min}-${max}-1` : `${control.urlPrefix}=${min * 1000}-${max * 1000}`])],
        }), "range");
    }, [navigate, control]);
}

export function RangeFilterGroup({ group, control }) {
    const t = useTranslation();
    const localized = useLocalized();
    const track = useTrack();
    const money = useMoneyFormat();
    const apply = useRangeFilter(control);
    const commit = useDebouncedCallback((range) => {
        track("accommodation.search_filter_range", { group: group.field, min: range[0], max: range[1] });
        apply(range);
    }, 500);
    const value = useMemo(() => [control.selectedMin, control.selectedMax], [control.selectedMin, control.selectedMax]);
    const format = useCallback((v) => (control.currency ? money(v) : `${v} km`), [control.currency, money]);
    const isPrice = Boolean(control.currency);
    return (
        <RangeSlider
            min={control.min}
            max={control.max}
            step={control.step}
            value={value}
            onChange={commit}
            histogram={control.histogram}
            formatValue={format}
            labels={{ min: t(isPrice ? "filters.price_min" : "filters.distance_min"), max: t(isPrice ? "filters.price_max" : "filters.distance_max") }}
            testId={`filter-slider-${group.field}`}
            aria-label={localized(control.a11yLabel)}
        />
    );
}
