import { memo } from "react";
import { Card, Skeleton, Stack, Text } from "@kit/index.js";
import { ErrorBoundary, TrackingScope, Translate, useExperimentTracking } from "travel-platform";
import "./catalog.js";
import { CheckboxFilterGroup } from "./CheckboxFilterGroup.jsx";
import { RangeFilterGroup } from "./RangeFilterGroup.jsx";
import { StepperFilterGroup } from "./StepperFilterGroup.jsx";
import { MapTeaser } from "./MapTeaser.jsx";
import { FilterGroupFrame } from "./FilterGroupFrame.jsx";
import styles from "./FilterPanel.module.css";

const CONTROLS = {
    CheckboxListControl: CheckboxFilterGroup,
    RangeSliderControl: RangeFilterGroup,
    StepperListControl: StepperFilterGroup,
};

const FilterGroup = memo(function FilterGroup({ group }) {
    useExperimentTracking(group.tracking);
    const Control = CONTROLS[group.control.__typename];
    return (
        <ErrorBoundary name={`filter-${group.field}`}>
            <FilterGroupFrame group={group}>
                <Control group={group} control={group.control} />
            </FilterGroupFrame>
        </ErrorBoundary>
    );
});

function FilterPanelSkeleton() {
    const rows = [];
    for (let i = 0; i < 6; i++)
        rows.push(<Skeleton key={i} height={20} />);
    return <Stack gap={3} className={styles.skeleton}>{rows}</Stack>;
}

export default function FilterPanel({ groups, mapPreview, loading }) {
    return (
        <TrackingScope surface="filters">
            <aside className={styles.panel} aria-busy={loading} data-testid="filters-sidebar">
                {mapPreview ? <MapTeaser preview={mapPreview} /> : null}
                <Card variant="outlined" padding={false} className={styles.card}>
                    <Text as="h2" variant="strong_1" className={styles.heading}><Translate id="filters.heading" /></Text>
                    {groups ? groups.map((group) => <FilterGroup key={group.field} group={group} />) : <FilterPanelSkeleton />}
                </Card>
            </aside>
        </TrackingScope>
    );
}
